-- Expand the ordered N5/N4 grammar curriculum and install the learner progress table
-- used by the grammar actions and dashboard. Safe to apply to existing local databases.
begin;

alter table public.grammar_points
  add column if not exists category text not null default 'Foundations',
  add column if not exists difficulty text not null default 'Core',
  add column if not exists sort_order integer not null default 100;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'grammar_points_difficulty_check'
      and conrelid = 'public.grammar_points'::regclass
  ) then
    alter table public.grammar_points
      add constraint grammar_points_difficulty_check
      check (difficulty in ('Beginner', 'Core', 'Challenge'));
  end if;
end;
$$;

create index if not exists grammar_points_level_order_idx
  on public.grammar_points (jlpt_level, sort_order, title);

create table if not exists public.user_grammar_progress (
  user_id uuid not null references auth.users(id) on delete cascade,
  grammar_id uuid not null references public.grammar_points(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, grammar_id)
);

create index if not exists user_grammar_progress_grammar_idx
  on public.user_grammar_progress (grammar_id, user_id);

alter table public.user_grammar_progress enable row level security;
revoke all privileges on public.user_grammar_progress from public, anon, authenticated;
grant select, insert, delete on public.user_grammar_progress to authenticated;
grant all privileges on public.user_grammar_progress to service_role;

drop policy if exists grammar_progress_read_own on public.user_grammar_progress;
create policy grammar_progress_read_own
  on public.user_grammar_progress for select to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists grammar_progress_insert_published on public.user_grammar_progress;
create policy grammar_progress_insert_published
  on public.user_grammar_progress for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and exists (
      select 1 from public.grammar_points g
      where g.id = grammar_id and g.publication_status = 'published'
    )
  );

drop policy if exists grammar_progress_delete_own on public.user_grammar_progress;
create policy grammar_progress_delete_own
  on public.user_grammar_progress for delete to authenticated
  using (user_id = (select auth.uid()));

with curriculum as (
  select
    (item->>'jlpt_level')::public.jlpt_level as jlpt_level,
    item->>'title' as title,
    item->>'pattern' as pattern,
    item->>'explanation' as explanation,
    item->>'formation' as formation,
    coalesce(item->'examples', '[]'::jsonb) as examples,
    coalesce(item->'common_mistakes', '[]'::jsonb) as common_mistakes,
    item->>'category' as category,
    item->>'difficulty' as difficulty,
    (item->>'sort_order')::integer as sort_order
  from jsonb_array_elements($curriculum$[{"jlpt_level":"N5","sort_order":10,"title":"Topic marker は","pattern":"N は ...","explanation":"は introduces the topic that the speaker is talking about. Although written with the hiragana は, the topic particle is pronounced wa. It often contrasts the topic with other people or things.","formation":"Topic + は + comment","category":"Particles","difficulty":"Beginner","examples":[{"japanese":"わたしは学生です。","romaji":"Watashi wa gakusei desu.","meaning":"I am a student."},{"japanese":"今日は雨です。","romaji":"Kyou wa ame desu.","meaning":"It is raining today."}],"common_mistakes":["Do not pronounce the topic particle as ha.","は marks the topic; it does not automatically identify the grammatical subject."]},{"jlpt_level":"N5","sort_order":20,"title":"Subject marker が","pattern":"N が ...","explanation":"が marks the grammatical subject, identifies something newly noticed, or answers a question about who or what performs an action. It commonly appears with あります, います, and expressions of ability or preference.","formation":"Subject + が + predicate","category":"Particles","difficulty":"Beginner","examples":[{"japanese":"ねこがいます。","romaji":"Neko ga imasu.","meaning":"There is a cat."},{"japanese":"だれが来ますか。","romaji":"Dare ga kimasu ka.","meaning":"Who is coming?"}],"common_mistakes":["Do not replace が with は when answering a direct who or what question without considering the focus.","Remember that は and が have different information-focus roles."]},{"jlpt_level":"N5","sort_order":30,"title":"Direct object marker を","pattern":"N を V","explanation":"を marks the direct object affected by an action. It is written を and pronounced o. It can also mark a route or space passed through with certain movement verbs.","formation":"Object + を + action verb","category":"Particles","difficulty":"Beginner","examples":[{"japanese":"水を飲みます。","romaji":"Mizu o nomimasu.","meaning":"I drink water."},{"japanese":"毎朝、本を読みます。","romaji":"Maiasa, hon o yomimasu.","meaning":"I read a book every morning."}],"common_mistakes":["Do not pronounce を as wo in ordinary modern speech.","Do not confuse the object marker を with the location marker で."]},{"jlpt_level":"N5","sort_order":40,"title":"Destination に","pattern":"Place に 行きます","explanation":"に marks the destination or arrival point with movement verbs such as 行きます, 来ます, and 帰ります. It can also mark the person who receives something or the location where something exists.","formation":"Destination + に + 行く / 来る / 帰る","category":"Particles","difficulty":"Beginner","examples":[{"japanese":"学校に行きます。","romaji":"Gakkou ni ikimasu.","meaning":"I go to school."},{"japanese":"友だちに手紙を書きます。","romaji":"Tomodachi ni tegami o kakimasu.","meaning":"I write a letter to a friend."}],"common_mistakes":["Do not use に for the place where an action is performed; use で for that meaning.","With movement verbs, に marks the destination rather than the route."]},{"jlpt_level":"N5","sort_order":50,"title":"Place of action で","pattern":"Place で V","explanation":"で marks the place where an activity or action takes place. It also marks the means or tool used to perform an action, such as a language, vehicle, or instrument.","formation":"Place / means + で + action","category":"Particles","difficulty":"Beginner","examples":[{"japanese":"図書館で勉強します。","romaji":"Toshokan de benkyou shimasu.","meaning":"I study at the library."},{"japanese":"はしでご飯を食べます。","romaji":"Hashi de gohan o tabemasu.","meaning":"I eat rice with chopsticks."}],"common_mistakes":["Use に rather than で for the location where a person or thing exists.","Do not confuse a destination with the place where an action occurs."]},{"jlpt_level":"N5","sort_order":60,"title":"Noun connection and possession の","pattern":"N1 の N2","explanation":"の connects nouns. It can show ownership, affiliation, origin, material, topic, or a category relationship. The first noun describes or identifies the second noun.","formation":"Noun 1 + の + Noun 2","category":"Particles","difficulty":"Beginner","examples":[{"japanese":"これはわたしの本です。","romaji":"Kore wa watashi no hon desu.","meaning":"This is my book."},{"japanese":"日本語の先生です。","romaji":"Nihongo no sensei desu.","meaning":"I am a Japanese-language teacher."}],"common_mistakes":["Do not reverse the noun order: the owner or qualifier normally comes first.","の links nouns; it is not a replacement for は in the main sentence."]},{"jlpt_level":"N5","sort_order":70,"title":"Direction marker へ","pattern":"Place へ 行きます","explanation":"へ marks the direction toward which someone moves. It is written へ but pronounced e when used as a particle. に emphasizes the destination or arrival point, while へ emphasizes direction.","formation":"Place + へ + movement verb","category":"Particles","difficulty":"Beginner","examples":[{"japanese":"日本へ行きます。","romaji":"Nihon e ikimasu.","meaning":"I am going to Japan."},{"japanese":"駅へ歩きます。","romaji":"Eki e arukimasu.","meaning":"I walk toward the station."}],"common_mistakes":["Pronounce the particle へ as e, not he.","Do not assume へ and に are interchangeable in every sentence."]},{"jlpt_level":"N5","sort_order":80,"title":"Complete listing and accompaniment と","pattern":"N と N","explanation":"と joins nouns in a complete list. With a person, it can mean with. In contrast, や introduces a non-exhaustive list of examples.","formation":"Noun + と + Noun","category":"Particles","difficulty":"Beginner","examples":[{"japanese":"パンと牛乳を買います。","romaji":"Pan to gyuunyuu o kaimasu.","meaning":"I buy bread and milk."},{"japanese":"友だちと映画を見ます。","romaji":"Tomodachi to eiga o mimasu.","meaning":"I watch a film with a friend."}],"common_mistakes":["Use と when the list is presented as complete; use や for examples among other items.","The meaning with is different from the listing meaning, so read the context."]},{"jlpt_level":"N5","sort_order":90,"title":"Also / too も","pattern":"N も ...","explanation":"も means also or too and often replaces は or が when the same statement applies to an additional person or thing. It can also combine with quantities to mean as many as or even.","formation":"N + も + predicate","category":"Particles","difficulty":"Beginner","examples":[{"japanese":"わたしも学生です。","romaji":"Watashi mo gakusei desu.","meaning":"I am a student too."},{"japanese":"水もお茶も飲みます。","romaji":"Mizu mo ocha mo nomimasu.","meaning":"I drink both water and tea."}],"common_mistakes":["も usually replaces the topic or subject particle rather than being stacked after it.","Check whether the sentence means also, even, or as many as in context."]},{"jlpt_level":"N5","sort_order":100,"title":"Polite copula です","pattern":"N / な-adjective です","explanation":"です makes noun and な-adjective predicates polite. With nouns and な-adjectives it is a copula, not a verb meaning to exist. It can also follow い-adjectives as a politeness marker.","formation":"Noun / な-adjective + です","category":"Sentence patterns","difficulty":"Beginner","examples":[{"japanese":"田中さんは先生です。","romaji":"Tanaka-san wa sensei desu.","meaning":"Mr./Ms. Tanaka is a teacher."},{"japanese":"この町は静かです。","romaji":"Kono machi wa shizuka desu.","meaning":"This town is quiet."}],"common_mistakes":["Do not add な before です after an ordinary な-adjective predicate.","Do not treat です as a lexical verb meaning exist."]},{"jlpt_level":"N5","sort_order":110,"title":"Polite negative noun predicate じゃありません","pattern":"N じゃありません","explanation":"じゃありません is the common polite negative form of a noun predicate. ではありません is a more formal alternative. The noun remains unchanged while the copula carries the negation.","formation":"Noun + じゃありません","category":"Sentence patterns","difficulty":"Beginner","examples":[{"japanese":"わたしは医者じゃありません。","romaji":"Watashi wa isha ja arimasen.","meaning":"I am not a doctor."},{"japanese":"これは日本の車じゃありません。","romaji":"Kore wa Nihon no kuruma ja arimasen.","meaning":"This is not a Japanese car."}],"common_mistakes":["Do not use じゃありません to negate an ordinary verb; use the verb negative form.","In formal writing, prefer ではありません."]},{"jlpt_level":"N5","sort_order":120,"title":"Question particle か","pattern":"Polite sentence + か","explanation":"か turns a polite statement into a yes-or-no question. In standard polite questions, it appears at the end of the sentence. Question words such as 何 and どこ can appear before the predicate.","formation":"Polite sentence + か","category":"Sentence patterns","difficulty":"Beginner","examples":[{"japanese":"田中さんは先生ですか。","romaji":"Tanaka-san wa sensei desu ka.","meaning":"Is Tanaka a teacher?"},{"japanese":"これは何ですか。","romaji":"Kore wa nan desu ka.","meaning":"What is this?"}],"common_mistakes":["Do not confuse か with the question word 何; they perform different jobs.","A question word does not remove the need for a natural sentence ending."]},{"jlpt_level":"N5","sort_order":130,"title":"Past noun predicate でした","pattern":"N でした","explanation":"でした is the polite past form of です for noun predicates. It describes a state or identity that was true in the past.","formation":"Noun + でした","category":"Sentence patterns","difficulty":"Beginner","examples":[{"japanese":"きのうは休みでした。","romaji":"Kinou wa yasumi deshita.","meaning":"Yesterday was a day off."},{"japanese":"子どものとき、学生でした。","romaji":"Kodomo no toki, gakusei deshita.","meaning":"I was a student when I was a child."}],"common_mistakes":["Use でした for past noun predicates; use ました for past actions.","Do not use です and でした together."]},{"jlpt_level":"N5","sort_order":140,"title":"Polite non-past verbs ます","pattern":"V-stem + ます","explanation":"ます is attached to the verb stem to express polite non-past actions. Non-past Japanese verbs can describe both habits and future plans; context or a time expression clarifies which meaning is intended.","formation":"Verb stem + ます","category":"Verbs","difficulty":"Beginner","examples":[{"japanese":"毎日、日本語を勉強します。","romaji":"Mainichi, Nihongo o benkyou shimasu.","meaning":"I study Japanese every day."},{"japanese":"あした東京へ行きます。","romaji":"Ashita Toukyou e ikimasu.","meaning":"I will go to Tokyo tomorrow."}],"common_mistakes":["ます does not mean only present time; it can refer to the future.","Learn the correct stem for each verb group instead of adding ます directly to every dictionary form."]},{"jlpt_level":"N5","sort_order":150,"title":"Polite negative verbs ません","pattern":"V-stem + ません","explanation":"ません is the polite negative non-past form. It can describe something that does not happen regularly or an action that the speaker will not do.","formation":"Verb stem + ません","category":"Verbs","difficulty":"Beginner","examples":[{"japanese":"コーヒーを飲みません。","romaji":"Koohii o nomimasen.","meaning":"I do not drink coffee."},{"japanese":"今日は学校へ行きません。","romaji":"Kyou wa gakkou e ikimasen.","meaning":"I will not go to school today."}],"common_mistakes":["Do not attach ません directly to the dictionary form.","Use ませんでした for a negative past action."]},{"jlpt_level":"N5","sort_order":160,"title":"Polite past verbs ました","pattern":"V-stem + ました","explanation":"ました is the polite past form of a verb. It reports a completed action or event. The verb stem is the same stem used with ます.","formation":"Verb stem + ました","category":"Verbs","difficulty":"Beginner","examples":[{"japanese":"昨日、映画を見ました。","romaji":"Kinou, eiga o mimashita.","meaning":"I watched a film yesterday."},{"japanese":"朝ご飯を食べました。","romaji":"Asagohan o tabemashita.","meaning":"I ate breakfast."}],"common_mistakes":["Do not confuse ました with でした: the former attaches to verbs and the latter to noun predicates.","Do not use ました for a future action."]},{"jlpt_level":"N5","sort_order":170,"title":"Polite past negative verbs ませんでした","pattern":"V-stem + ませんでした","explanation":"ませんでした expresses that an action did not happen in the past. It is formed by attaching ませんでした to the verb stem.","formation":"Verb stem + ませんでした","category":"Verbs","difficulty":"Beginner","examples":[{"japanese":"テレビを見ませんでした。","romaji":"Terebi o mimasen deshita.","meaning":"I did not watch television."},{"japanese":"先週、旅行しませんでした。","romaji":"Senshuu, ryokou shimasen deshita.","meaning":"I did not travel last week."}],"common_mistakes":["Do not add でした after an already-past affirmative ました.","Keep the verb stem unchanged when switching between polite forms."]},{"jlpt_level":"N5","sort_order":180,"title":"Existence あります and います","pattern":"N が あります / います","explanation":"あります describes the existence or presence of inanimate things and plants. います is used for people and animals. The place where something exists is commonly marked with に.","formation":"Place に N が あります / います","category":"Sentence patterns","difficulty":"Core","examples":[{"japanese":"つくえの上に本があります。","romaji":"Tsukue no ue ni hon ga arimasu.","meaning":"There is a book on the desk."},{"japanese":"部屋にねこがいます。","romaji":"Heya ni neko ga imasu.","meaning":"There is a cat in the room."}],"common_mistakes":["Use います for people and animals, not ordinary inanimate objects.","Use に for the place of existence and が for the thing that exists."]},{"jlpt_level":"N5","sort_order":190,"title":"Past い-adjectives かったです","pattern":"い-adjective: い → かったです","explanation":"To make an い-adjective past, remove the final い and add かったです. The resulting form describes a quality that was true in the past.","formation":"い-adjective stem + かったです","category":"Adjectives","difficulty":"Core","examples":[{"japanese":"昨日は暑かったです。","romaji":"Kinou wa atsukatta desu.","meaning":"It was hot yesterday."},{"japanese":"この本はおもしろかったです。","romaji":"Kono hon wa omoshirokatta desu.","meaning":"This book was interesting."}],"common_mistakes":["Do not keep the final い before adding かったです.","いい is irregular in the past: よかったです."]},{"jlpt_level":"N5","sort_order":200,"title":"Want to do たいです","pattern":"V-stem + たいです","explanation":"たいです expresses the speaker's desire to perform an action. It conjugates like an い-adjective. The object of the desired action is commonly marked with を, although が is also possible in some contexts.","formation":"Verb stem + たいです","category":"Verbs","difficulty":"Core","examples":[{"japanese":"日本へ行きたいです。","romaji":"Nihon e ikitai desu.","meaning":"I want to go to Japan."},{"japanese":"冷たい水を飲みたいです。","romaji":"Tsumetai mizu o nomitai desu.","meaning":"I want to drink cold water."}],"common_mistakes":["Attach たい to the verb stem, not to the dictionary form.","たい describes desire; use ほしい for wanting a thing or object."]},{"jlpt_level":"N5","sort_order":210,"title":"Please do てください","pattern":"V-て + ください","explanation":"てください makes a polite request. First conjugate the verb into its て-form, then add ください. The expression is useful for instructions and everyday requests.","formation":"Verb て-form + ください","category":"Requests and permission","difficulty":"Core","examples":[{"japanese":"ここに名前を書いてください。","romaji":"Koko ni namae o kaite kudasai.","meaning":"Please write your name here."},{"japanese":"ゆっくり話してください。","romaji":"Yukkuri hanashite kudasai.","meaning":"Please speak slowly."}],"common_mistakes":["The correct て-form depends on the verb group and final sound.","ください is polite, but it can still sound direct when used with superiors."]},{"jlpt_level":"N5","sort_order":220,"title":"Permission てもいいです","pattern":"V-て + もいいです","explanation":"てもいいです asks for or grants permission. In a question, it politely asks whether an action is allowed. In a statement, it says that the action is permitted.","formation":"Verb て-form + もいいです","category":"Requests and permission","difficulty":"Core","examples":[{"japanese":"ここに座ってもいいですか。","romaji":"Koko ni suwatte mo ii desu ka.","meaning":"May I sit here?"},{"japanese":"写真を撮ってもいいです。","romaji":"Shashin o totte mo ii desu.","meaning":"You may take a photo."}],"common_mistakes":["Do not confuse permission てもいい with prohibition てはいけない.","The particle も remains in this expression."]},{"jlpt_level":"N5","sort_order":230,"title":"Prohibition てはいけません","pattern":"V-て + はいけません","explanation":"てはいけません expresses that an action is prohibited or must not be done. It is stronger than a simple negative statement and is commonly used for rules and instructions.","formation":"Verb て-form + はいけません","category":"Requests and permission","difficulty":"Core","examples":[{"japanese":"ここで写真を撮ってはいけません。","romaji":"Koko de shashin o totte wa ikemasen.","meaning":"You must not take photographs here."},{"japanese":"この部屋に入ってはいけません。","romaji":"Kono heya ni haitte wa ikemasen.","meaning":"You must not enter this room."}],"common_mistakes":["Use て-form before はいけません.","Do not interpret this as permission; it expresses prohibition."]},{"jlpt_level":"N5","sort_order":240,"title":"Giving a reason with から","pattern":"Reason から、result","explanation":"から connects a reason to a result. It can follow a plain form or a polite clause. When the reason is stated politely with a noun or な-adjective, ですから is also common.","formation":"Reason + から + result","category":"Connecting ideas","difficulty":"Core","examples":[{"japanese":"雨ですから、出かけません。","romaji":"Ame desu kara, dekakemasen.","meaning":"Because it is raining, I will not go out."},{"japanese":"忙しいですから、あとで電話します。","romaji":"Isogashii desu kara, ato de denwa shimasu.","meaning":"Because I am busy, I will call later."}],"common_mistakes":["Put the reason before から.","Do not use です after every plain-form verb before から."]},{"jlpt_level":"N5","sort_order":250,"title":"Comparison with より","pattern":"A は B より adjective","explanation":"より marks the comparison standard. The thing being described is introduced with は, and より identifies what it is compared against.","formation":"A は B より adjective です","category":"Comparisons","difficulty":"Core","examples":[{"japanese":"今日は昨日より暑いです。","romaji":"Kyou wa kinou yori atsui desu.","meaning":"Today is hotter than yesterday."},{"japanese":"犬はねこより大きいです。","romaji":"Inu wa neko yori ookii desu.","meaning":"Dogs are bigger than cats."}],"common_mistakes":["The noun after より is the comparison standard.","For a simple comparison, do not reverse which item is being described."]},{"jlpt_level":"N5","sort_order":260,"title":"Approximation ぐらい / くらい","pattern":"Number + ぐらい","explanation":"ぐらい and くらい follow a number or amount to express an approximate quantity, duration, or degree. Both forms are common in conversation.","formation":"Number / amount + ぐらい","category":"Numbers and time","difficulty":"Core","examples":[{"japanese":"駅まで十分ぐらいです。","romaji":"Eki made juppun gurai desu.","meaning":"It is about ten minutes to the station."},{"japanese":"毎日二時間くらい勉強します。","romaji":"Mainichi nijikan kurai benkyou shimasu.","meaning":"I study for about two hours every day."}],"common_mistakes":["ぐらい indicates approximation, not an exact count.","Use the appropriate counter with the number when the noun requires one."]},{"jlpt_level":"N5","sort_order":270,"title":"Specific time に","pattern":"Clock time + に + V","explanation":"に marks a specific clock time when an action takes place. It is commonly used with hours, dates, and days of the week when the time is treated as a point. It is usually omitted with relative expressions such as today and tomorrow.","formation":"Specific time + に + action","category":"Particles","difficulty":"Core","examples":[{"japanese":"毎朝六時に起きます。","romaji":"Maiasa roku-ji ni okimasu.","meaning":"I get up at six every morning."},{"japanese":"月曜日にテストがあります。","romaji":"Getsuyoubi ni tesuto ga arimasu.","meaning":"There is a test on Monday."}],"common_mistakes":["Do not normally add に after きょう, あした, きのう, or まいにち.","Use に for a specific point in time, not a time span such as two hours."]},{"jlpt_level":"N5","sort_order":280,"title":"Demonstrative pronouns これ / それ / あれ","pattern":"これ / それ / あれ + は","explanation":"これ refers to something near the speaker, それ to something near the listener or just mentioned, and あれ to something away from both. These forms stand alone and do not directly modify a noun.","formation":"これ / それ / あれ + は + noun predicate","category":"Demonstratives","difficulty":"Beginner","examples":[{"japanese":"これはわたしのかばんです。","romaji":"Kore wa watashi no kaban desu.","meaning":"This is my bag."},{"japanese":"あれは学校です。","romaji":"Are wa gakkou desu.","meaning":"That over there is a school."}],"common_mistakes":["Use この / その / あの before a noun; do not attach them directly to です.","Choose the form based on the speaker-listener distance and discourse context."]},{"jlpt_level":"N5","sort_order":290,"title":"Demonstrative modifiers この / その / あの","pattern":"この / その / あの + N","explanation":"この, その, and あの modify a noun directly. They correspond roughly to this, that near you or previously mentioned, and that over there. They cannot stand alone without the noun they modify.","formation":"この / その / あの + noun","category":"Demonstratives","difficulty":"Beginner","examples":[{"japanese":"この本はおもしろいです。","romaji":"Kono hon wa omoshiroi desu.","meaning":"This book is interesting."},{"japanese":"あの人は田中さんです。","romaji":"Ano hito wa Tanaka-san desu.","meaning":"That person over there is Mr./Ms. Tanaka."}],"common_mistakes":["Do not add の between この and the noun.","Use これ when the noun is not stated and この when the noun follows."]},{"jlpt_level":"N5","sort_order":300,"title":"Place words ここ / そこ / あそこ","pattern":"ここ / そこ / あそこ + は","explanation":"ここ means here near the speaker, そこ means there near the listener or in the current context, and あそこ means over there away from both. They can be used with です or with location particles.","formation":"ここ / そこ / あそこ + は / に / で","category":"Demonstratives","difficulty":"Beginner","examples":[{"japanese":"ここは図書館です。","romaji":"Koko wa toshokan desu.","meaning":"This is the library."},{"japanese":"駅はあそこにあります。","romaji":"Eki wa asoko ni arimasu.","meaning":"The station is over there."}],"common_mistakes":["Use ここ for the speaker's location, not automatically for the listener's location.","When modifying a noun, use こちら / そちら / あちら or この / その / あの as appropriate."]},{"jlpt_level":"N5","sort_order":310,"title":"Question words どれ / どの / どこ","pattern":"どれ / どの + N / どこ","explanation":"どれ asks which one among things; どの must be followed by a noun; どこ asks where. These words usually occur before the predicate and can combine with particles such as が and に.","formation":"どれ / どの + noun / どこ + particle","category":"Questions","difficulty":"Core","examples":[{"japanese":"あなたのかばんはどれですか。","romaji":"Anata no kaban wa dore desu ka.","meaning":"Which one is your bag?"},{"japanese":"どの本を読みますか。","romaji":"Dono hon o yomimasu ka.","meaning":"Which book will you read?"}],"common_mistakes":["Do not use どの without a noun after it.","Use どこ for a place and どれ for a choice among things."]},{"jlpt_level":"N5","sort_order":320,"title":"Negative い-adjectives くないです","pattern":"い-adjective: い → くないです","explanation":"To make an い-adjective negative, remove the final い and add くないです. This means not and can describe a present or general quality.","formation":"い-adjective stem + くないです","category":"Adjectives","difficulty":"Core","examples":[{"japanese":"この部屋は広くないです。","romaji":"Kono heya wa hirokunai desu.","meaning":"This room is not spacious."},{"japanese":"今日は寒くないです。","romaji":"Kyou wa samukunai desu.","meaning":"It is not cold today."}],"common_mistakes":["Do not attach くないです without removing the final い.","いい becomes よくないです, not いくないです."]},{"jlpt_level":"N5","sort_order":330,"title":"な-adjective predicates and negatives","pattern":"な-adjective + です / じゃありません","explanation":"A な-adjective uses です at the end of a predicate. Before a noun it needs な. Its polite negative uses じゃありません or ではありません.","formation":"Predicate: な-adjective + です; modifier: な-adjective + な + noun","category":"Adjectives","difficulty":"Core","examples":[{"japanese":"この町は便利です。","romaji":"Kono machi wa benri desu.","meaning":"This town is convenient."},{"japanese":"静かな部屋が好きです。","romaji":"Shizuka na heya ga suki desu.","meaning":"I like quiet rooms."}],"common_mistakes":["Use な only when the adjective modifies a noun.","Do not apply い-adjective endings such as くない to な-adjectives."]},{"jlpt_level":"N5","sort_order":340,"title":"Let's do ましょう","pattern":"V-stem + ましょう","explanation":"ましょう is the polite volitional form. It proposes that the speaker and listener do something together or expresses a positive suggestion.","formation":"Verb stem + ましょう","category":"Verbs","difficulty":"Core","examples":[{"japanese":"いっしょに帰りましょう。","romaji":"Issho ni kaerimashou.","meaning":"Let's go home together."},{"japanese":"昼ご飯を食べましょう。","romaji":"Hirugohan o tabemashou.","meaning":"Let's eat lunch."}],"common_mistakes":["Use the verb stem rather than the dictionary form.","ましょう is a proposal; it is not the same as a plain future statement."]},{"jlpt_level":"N5","sort_order":350,"title":"Invitation ませんか","pattern":"V-stem + ませんか","explanation":"ませんか is a polite invitation. It literally has a negative question form, but pragmatically it asks whether the listener would like to join an activity.","formation":"Verb stem + ませんか","category":"Verbs","difficulty":"Core","examples":[{"japanese":"週末、映画を見ませんか。","romaji":"Shuumatsu, eiga o mimasen ka.","meaning":"Would you like to watch a film this weekend?"},{"japanese":"いっしょに昼ご飯を食べませんか。","romaji":"Issho ni hirugohan o tabemasen ka.","meaning":"Would you like to have lunch together?"}],"common_mistakes":["Do not translate this form as a plain refusal or negative statement.","Use ませんか for inviting the listener, and ましょう for proposing a shared action."]},{"jlpt_level":"N5","sort_order":360,"title":"Ongoing action and current state ています","pattern":"V-て + います","explanation":"ています describes an action currently in progress, a repeated habit, or a resulting state depending on the verb. Context determines which interpretation is natural.","formation":"Verb て-form + います","category":"Verbs","difficulty":"Challenge","examples":[{"japanese":"今、本を読んでいます。","romaji":"Ima, hon o yonde imasu.","meaning":"I am reading a book now."},{"japanese":"東京に住んでいます。","romaji":"Toukyou ni sunde imasu.","meaning":"I live in Tokyo."}],"common_mistakes":["Not every ています sentence describes an action happening at this exact moment.","Some verbs describe a resulting state, such as 住んでいます for live."]},{"jlpt_level":"N5","sort_order":370,"title":"Sequence after てから","pattern":"V-て + から","explanation":"てから means after doing something. It marks the first action as completed before the next action begins. The sequence is explicit and is useful for describing routines.","formation":"First action in て-form + から + next action","category":"Connecting ideas","difficulty":"Challenge","examples":[{"japanese":"手を洗ってから、ご飯を食べます。","romaji":"Te o aratte kara, gohan o tabemasu.","meaning":"I wash my hands before eating."},{"japanese":"宿題をしてから、テレビを見ます。","romaji":"Shukudai o shite kara, terebi o mimasu.","meaning":"I watch television after doing my homework."}],"common_mistakes":["The verb before から must be in て-form.","てから makes the order explicit; do not confuse it with a reason marker から."]},{"jlpt_level":"N5","sort_order":380,"title":"Before an action 前に","pattern":"V-dictionary + 前に","explanation":"前に means before. When it follows a verb, the verb stays in dictionary form. With a noun, use の前に. The clause before 前に describes the action that has not yet happened at the reference point.","formation":"Verb dictionary form + 前に / Noun + の前に","category":"Time expressions","difficulty":"Challenge","examples":[{"japanese":"寝る前に、歯を磨きます。","romaji":"Neru mae ni, ha o migakimasu.","meaning":"I brush my teeth before going to bed."},{"japanese":"食事の前に手を洗います。","romaji":"Shokuji no mae ni te o araimasu.","meaning":"I wash my hands before a meal."}],"common_mistakes":["Use the dictionary form before 前に, not the past form.","Use の between a noun and 前に."]},{"jlpt_level":"N5","sort_order":390,"title":"After an action 後で","pattern":"Vた + 後で","explanation":"後で means after. With a verb, use the short past form before 後で. With a noun, connect the noun using の. It can describe a later action in a sequence.","formation":"Verb past plain form + 後で / Noun + の後で","category":"Time expressions","difficulty":"Challenge","examples":[{"japanese":"宿題をした後で、ゲームをします。","romaji":"Shukudai o shita ato de, geemu o shimasu.","meaning":"I play a game after doing my homework."},{"japanese":"仕事の後で、買い物をします。","romaji":"Shigoto no ato de, kaimono o shimasu.","meaning":"I go shopping after work."}],"common_mistakes":["Use the plain past verb form before 後で.","Do not confuse 後で with てから; both sequence events but use different forms."]},{"jlpt_level":"N5","sort_order":400,"title":"Likes and dislikes が好き / 嫌い","pattern":"N が 好きです / 嫌いです","explanation":"好き and 嫌い are な-adjectives. The thing liked or disliked is commonly marked by が, while the person who has the preference is often marked by は.","formation":"Person は + thing が + 好き / 嫌い です","category":"Adjectives","difficulty":"Core","examples":[{"japanese":"わたしは日本料理が好きです。","romaji":"Watashi wa Nihon ryouri ga suki desu.","meaning":"I like Japanese food."},{"japanese":"弟は野菜が嫌いです。","romaji":"Otouto wa yasai ga kirai desu.","meaning":"My younger brother dislikes vegetables."}],"common_mistakes":["Use が for the object of preference in the standard pattern.","好き is not a verb; use 好きな before a noun."]},{"jlpt_level":"N4","sort_order":10,"title":"Explanatory tone んです / のです","pattern":"Plain form + んです","explanation":"んです adds an explanatory or contextual tone. It often gives a reason, background, or clarification for something the listener has asked or noticed. Nouns and な-adjectives take な before んです.","formation":"Verb / い-adjective plain form + んです; noun / な-adjective + な + んです","category":"Explanations","difficulty":"Core","examples":[{"japanese":"どうして遅れたんですか。","romaji":"Doushite okureta n desu ka.","meaning":"Why were you late?"},{"japanese":"頭が痛いんです。","romaji":"Atama ga itai n desu.","meaning":"The thing is, I have a headache."}],"common_mistakes":["Use な before んです after a noun or な-adjective.","んです is not a neutral replacement for です; it adds explanation or shared context."]},{"jlpt_level":"N4","sort_order":20,"title":"Appearance そうです","pattern":"V-masu stem / adjective stem + そうです","explanation":"そうです describes an appearance based on what the speaker can observe. With verbs, it suggests something is about to happen; with adjectives, it means something looks a certain way. Remove い from い-adjectives and な from な-adjectives.","formation":"V-masu stem + そうです; adjective stem + そうです","category":"Appearance and impressions","difficulty":"Core","examples":[{"japanese":"雨が降りそうです。","romaji":"Ame ga furisou desu.","meaning":"It looks like it is going to rain."},{"japanese":"このケーキはおいしそうです。","romaji":"Kono keeki wa oishisou desu.","meaning":"This cake looks delicious."}],"common_mistakes":["Do not confuse appearance そうです with hearsay そうです after a plain clause.","いい becomes よさそうです; ない becomes なさそうです."]},{"jlpt_level":"N4","sort_order":30,"title":"Hearsay そうです","pattern":"Plain clause + そうです","explanation":"そうです can report information heard from another person or source. The clause before it stays in plain form. It does not express the speaker's direct visual impression.","formation":"Plain form + そうです","category":"Reporting information","difficulty":"Core","examples":[{"japanese":"天気予報によると、明日は雨だそうです。","romaji":"Tenki yohou ni yoru to, ashita wa ame da sou desu.","meaning":"According to the forecast, it will rain tomorrow."},{"japanese":"田中さんは来月結婚するそうです。","romaji":"Tanaka-san wa raigetsu kekkon suru sou desu.","meaning":"I hear that Tanaka is getting married next month."}],"common_mistakes":["Use plain form before hearsay そうです; do not remove だ after a noun in a plain affirmative clause.","Look for a source such as によると to identify reported information."]},{"jlpt_level":"N4","sort_order":40,"title":"Inference ようです","pattern":"Plain form + ようです","explanation":"ようです expresses an inference or comparison based on evidence. It is more measured than a direct statement and can mean it seems, appears, or is like. Nouns and な-adjectives connect with のようです or なようです depending on use.","formation":"Plain form + ようです; Noun + のようです","category":"Appearance and impressions","difficulty":"Challenge","examples":[{"japanese":"外は寒いようです。","romaji":"Soto wa samui you desu.","meaning":"It seems cold outside."},{"japanese":"彼は先生のようです。","romaji":"Kare wa sensei no you desu.","meaning":"He seems to be a teacher."}],"common_mistakes":["Do not confuse ようです inference with hearsay そうです.","For a noun comparison, use のようです."]},{"jlpt_level":"N4","sort_order":50,"title":"Informal comparison みたいです","pattern":"Plain form / noun + みたいです","explanation":"みたいです expresses an impression, resemblance, or tentative inference. It is common in conversation and generally more casual than ようです. It can modify a noun as みたいな and an adverbial phrase as みたいに.","formation":"Noun / plain clause + みたいです; みたいな + noun","category":"Appearance and impressions","difficulty":"Core","examples":[{"japanese":"あの人は日本人みたいです。","romaji":"Ano hito wa Nihonjin mitai desu.","meaning":"That person seems to be Japanese."},{"japanese":"今日は春みたいな天気です。","romaji":"Kyou wa haru mitai na tenki desu.","meaning":"The weather today is like spring."}],"common_mistakes":["Use みたいな before a noun and みたいに before an action or adjective.","みたい is conversational; choose よう when a more formal tone is needed."]},{"jlpt_level":"N4","sort_order":60,"title":"Typical quality らしいです","pattern":"Noun / plain clause + らしいです","explanation":"らしいです expresses hearsay or a quality typical of a person or thing. The exact nuance depends on context: information reported from others or an inference that something is characteristic of its category.","formation":"Noun / plain clause + らしいです","category":"Reporting information","difficulty":"Challenge","examples":[{"japanese":"田中さんは来ないらしいです。","romaji":"Tanaka-san wa konai rashii desu.","meaning":"Apparently, Tanaka is not coming."},{"japanese":"今日は春らしい暖かい日です。","romaji":"Kyou wa haru rashii atatakai hi desu.","meaning":"Today is a warm day typical of spring."}],"common_mistakes":["Distinguish hearsay らしい from the adjective meaning typical of.","Do not use らしい as a direct substitute for every instance of そうです."]},{"jlpt_level":"N4","sort_order":70,"title":"Purpose ために","pattern":"V-dictionary / Nの + ために","explanation":"ために expresses a purpose or benefit. It often follows an intentional action or a noun and explains what the action is intended to achieve or whom it benefits.","formation":"Verb dictionary form + ために; Noun + の + ために","category":"Purpose and intention","difficulty":"Core","examples":[{"japanese":"日本で働くために、日本語を勉強しています。","romaji":"Nihon de hataraku tame ni, Nihongo o benkyou shite imasu.","meaning":"I am studying Japanese in order to work in Japan."},{"japanese":"家族のために料理を作ります。","romaji":"Kazoku no tame ni ryouri o tsukurimasu.","meaning":"I cook for my family."}],"common_mistakes":["Use dictionary form before ために for an intentional action.","Do not confuse purpose ために with reason ために in a past or negative context."]},{"jlpt_level":"N4","sort_order":80,"title":"Goal or desired result ように","pattern":"V-dictionary / Vない + ように","explanation":"ように expresses a goal or desired state, especially when the result is not fully under direct control. It often appears with potential verbs, verbs of understanding, or negative forms.","formation":"Verb dictionary / negative form + ように","category":"Purpose and intention","difficulty":"Challenge","examples":[{"japanese":"日本語が話せるように、毎日練習します。","romaji":"Nihongo ga hanaseru you ni, mainichi renshuu shimasu.","meaning":"I practise every day so that I can speak Japanese."},{"japanese":"忘れないように、メモします。","romaji":"Wasurenai you ni, memo shimasu.","meaning":"I make a note so that I do not forget."}],"common_mistakes":["Use ように for a desired state or ability; ために more often marks an intentional action.","Keep the negative form when the goal is to avoid something."]},{"jlpt_level":"N4","sort_order":90,"title":"Condition なら","pattern":"Noun / plain form + なら","explanation":"なら takes a topic or situation already raised and presents a condition based on it. It often means if that is the case or if you are talking about. It is useful for giving advice or responding to a premise.","formation":"Noun / plain clause + なら","category":"Conditionals","difficulty":"Challenge","examples":[{"japanese":"日本へ行くなら、京都にも行ってください。","romaji":"Nihon e iku nara, Kyoto ni mo itte kudasai.","meaning":"If you are going to Japan, please visit Kyoto too."},{"japanese":"時間がないなら、タクシーで行きましょう。","romaji":"Jikan ga nai nara, takushii de ikimashou.","meaning":"If you do not have time, let's go by taxi."}],"common_mistakes":["なら often responds to information already mentioned, rather than describing a general law.","Do not use なら as a mechanical replacement for every conditional."]},{"jlpt_level":"N4","sort_order":100,"title":"Natural condition と","pattern":"V-dictionary + と","explanation":"と expresses a predictable result or natural consequence when one condition is met. It is used for rules, instructions, habits, and cause-and-effect relationships, not usually for a speaker's direct request or invitation in the result clause.","formation":"Verb dictionary form + と + predictable result","category":"Conditionals","difficulty":"Challenge","examples":[{"japanese":"このボタンを押すと、ドアが開きます。","romaji":"Kono botan o osu to, doa ga akimasu.","meaning":"When you press this button, the door opens."},{"japanese":"春になると、桜が咲きます。","romaji":"Haru ni naru to, sakura ga sakimasu.","meaning":"When spring comes, cherry blossoms bloom."}],"common_mistakes":["Avoid commands or invitations in the result clause of a general と conditional.","Use と for predictable or automatic results, not every hypothetical situation."]},{"jlpt_level":"N4","sort_order":110,"title":"Hypothetical condition ば","pattern":"V / adjective conditional ば","explanation":"ば creates a hypothetical or general condition. Verb forms vary by group: replace the final う-row sound with the corresponding え-row sound and add ば; adjectives use the appropriate conditional form.","formation":"Verb e-row + ば; い-adjective: ければ; な-adjective / noun: ならば","category":"Conditionals","difficulty":"Challenge","examples":[{"japanese":"時間があれば、手伝います。","romaji":"Jikan ga areba, tetsudaimasu.","meaning":"If I have time, I will help."},{"japanese":"安ければ、買いたいです。","romaji":"Yasukereba, kaitai desu.","meaning":"If it is cheap, I want to buy it."}],"common_mistakes":["Conjugate each verb group correctly; do not add ば to the dictionary form unchanged.","ば often introduces a general or hypothetical condition; check whether a past event is being discussed."]},{"jlpt_level":"N4","sort_order":120,"title":"Real or hypothetical condition たら","pattern":"Vた + ら","explanation":"たら is a flexible conditional meaning if or when. It is formed by adding ら to the plain past form. It can describe a completed condition and can naturally precede requests, suggestions, or commands.","formation":"Verb past plain form + ら","category":"Conditionals","difficulty":"Core","examples":[{"japanese":"家に帰ったら、電話してください。","romaji":"Ie ni kaettara, denwa shite kudasai.","meaning":"Please call me when you get home."},{"japanese":"安かったら、買います。","romaji":"Yasukattara, kaimasu.","meaning":"If it is inexpensive, I will buy it."}],"common_mistakes":["Use the past plain form before ら, even when the sentence refers to the future.","Do not confuse たら with たことがある, which expresses experience."]},{"jlpt_level":"N4","sort_order":130,"title":"Reason ので","pattern":"Plain form + ので","explanation":"ので gives a reason or cause in a relatively soft and explanatory way. It often sounds less direct than から. Nouns and な-adjectives generally connect with な before ので.","formation":"Verb / い-adjective plain form + ので; noun / な-adjective + な + ので","category":"Connecting ideas","difficulty":"Core","examples":[{"japanese":"雨が降っているので、出かけません。","romaji":"Ame ga futte iru node, dekakemasen.","meaning":"Because it is raining, I will not go out."},{"japanese":"日曜日なので、銀行は休みです。","romaji":"Nichiyoubi na node, ginkou wa yasumi desu.","meaning":"Because it is Sunday, the bank is closed."}],"common_mistakes":["Use な before ので after a noun or な-adjective.","ので usually softens an explanation; it is not identical in tone to から."]},{"jlpt_level":"N4","sort_order":140,"title":"Unexpected contrast のに","pattern":"Plain form + のに","explanation":"のに expresses an unexpected or disappointing result despite an expectation. It often means although, even though, or despite the fact that. Nouns and な-adjectives use な before のに.","formation":"Verb / い-adjective plain form + のに; noun / な-adjective + な + のに","category":"Connecting ideas","difficulty":"Challenge","examples":[{"japanese":"勉強したのに、試験に合格しませんでした。","romaji":"Benkyou shita noni, shiken ni goukaku shimasen deshita.","meaning":"Although I studied, I did not pass the exam."},{"japanese":"安いのに、とてもおいしいです。","romaji":"Yasui noni, totemo oishii desu.","meaning":"Although it is cheap, it is very delicious."}],"common_mistakes":["Use のに when the outcome is contrary to an expectation.","Do not confuse のに with the purpose particle のに used in other constructions."]},{"jlpt_level":"N4","sort_order":150,"title":"Adding reasons し","pattern":"Plain form + し","explanation":"し lists reasons or characteristics and often implies that the list is not exhaustive. It can connect several clauses and is useful when supporting an opinion or explaining a choice.","formation":"Plain clause + し (+ reason / clause)","category":"Connecting ideas","difficulty":"Core","examples":[{"japanese":"この店は安いし、おいしいし、よく来ます。","romaji":"Kono mise wa yasui shi, oishii shi, yoku kimasu.","meaning":"This restaurant is inexpensive and delicious, so I come often."},{"japanese":"今日は雨だし、寒いし、家にいます。","romaji":"Kyou wa ame da shi, samui shi, ie ni imasu.","meaning":"It is rainy and cold today, so I will stay home."}],"common_mistakes":["し can list multiple supporting reasons; do not treat it as a simple equivalent of と.","Keep the predicate forms consistent before し."]},{"jlpt_level":"N4","sort_order":160,"title":"Even if ても","pattern":"V-て / adjective + も","explanation":"ても expresses concession: even if or even though. It says that the result remains true despite the condition. For い-adjectives use くても; for nouns and な-adjectives use でも.","formation":"Verb て-form + も; い-adjective くても; noun / な-adjective でも","category":"Connecting ideas","difficulty":"Core","examples":[{"japanese":"雨が降っても、出かけます。","romaji":"Ame ga futte mo, dekakemasu.","meaning":"Even if it rains, I will go out."},{"japanese":"高くても、この時計を買います。","romaji":"Takakute mo, kono tokei o kaimasu.","meaning":"Even if it is expensive, I will buy this watch."}],"common_mistakes":["Do not confuse concessive ても with permission てもいいです.","Use the correct connector for verbs, い-adjectives, nouns, and な-adjectives."]},{"jlpt_level":"N4","sort_order":170,"title":"Completion or regret てしまう","pattern":"V-て + しまう","explanation":"てしまう can show that an action has been completed fully, or that an undesirable event happened unintentionally. In conversation it often contracts to ちゃう or じゃう.","formation":"Verb て-form + しまう","category":"Verb nuance","difficulty":"Challenge","examples":[{"japanese":"宿題を全部してしまいました。","romaji":"Shukudai o zenbu shite shimaimashita.","meaning":"I finished all of my homework."},{"japanese":"財布を忘れてしまいました。","romaji":"Saifu o wasurete shimaimashita.","meaning":"I unfortunately forgot my wallet."}],"common_mistakes":["てしまう can express completion as well as regret; context determines the nuance.","Do not treat the contracted ちゃう / じゃう as formal writing."]},{"jlpt_level":"N4","sort_order":180,"title":"Preparation ておく","pattern":"V-て + おく","explanation":"ておく describes doing something in advance for a future purpose or leaving something in a particular state. In conversation it often contracts to とく.","formation":"Verb て-form + おく","category":"Verb nuance","difficulty":"Core","examples":[{"japanese":"旅行の前にホテルを予約しておきます。","romaji":"Ryokou no mae ni hoteru o yoyaku shite okimasu.","meaning":"I will book a hotel in advance of the trip."},{"japanese":"窓を開けておいてください。","romaji":"Mado o akete oite kudasai.","meaning":"Please leave the window open."}],"common_mistakes":["ておく emphasizes preparation or maintaining a state, not simply a sequence of actions.","The shortened とく is conversational."]},{"jlpt_level":"N4","sort_order":190,"title":"Trying something てみる","pattern":"V-て + みる","explanation":"てみる means to try doing something to see what happens or how it feels. It focuses on the attempt or experience rather than on whether the action succeeds.","formation":"Verb て-form + みる","category":"Verb nuance","difficulty":"Core","examples":[{"japanese":"新しい料理を作ってみます。","romaji":"Atarashii ryouri o tsukutte mimasu.","meaning":"I will try making a new dish."},{"japanese":"この靴を履いてみてもいいですか。","romaji":"Kono kutsu o haite mite mo ii desu ka.","meaning":"May I try these shoes on?"}],"common_mistakes":["The verb みる here is grammaticalized and does not mean simply see with your eyes.","Conjugate the first verb into て-form before みる."]},{"jlpt_level":"N4","sort_order":200,"title":"Movement toward the speaker てくる","pattern":"V-て + くる","explanation":"てくる can show movement toward the speaker, a change that has developed up to the present, or an action done and then followed by a return. The precise meaning depends on context.","formation":"Verb て-form + くる","category":"Verb direction and change","difficulty":"Challenge","examples":[{"japanese":"ちょっと飲み物を買ってきます。","romaji":"Chotto nomimono o katte kimasu.","meaning":"I will go buy a drink and come back."},{"japanese":"日本語が少し分かってきました。","romaji":"Nihongo ga sukoshi wakatte kimashita.","meaning":"I have gradually started to understand a little Japanese."}],"common_mistakes":["てくる is not always physical movement; it can express a change developing toward now.","Check whether the context describes going and returning or gradual change."]},{"jlpt_level":"N4","sort_order":210,"title":"Movement away or continuation ていく","pattern":"V-て + いく","explanation":"ていく can describe movement away from the speaker or a change that continues from now into the future. It is often contrasted with てくる, which moves toward the speaker or the present.","formation":"Verb て-form + いく","category":"Verb direction and change","difficulty":"Challenge","examples":[{"japanese":"駅まで歩いていきます。","romaji":"Eki made aruite ikimasu.","meaning":"I will walk to the station."},{"japanese":"これから人口が減っていくでしょう。","romaji":"Kore kara jinkou ga hette iku deshou.","meaning":"The population will probably continue to decrease from now on."}],"common_mistakes":["Do not assume ていく always means go on foot; it can express future continuation.","Contrast the direction or time perspective with てくる."]},{"jlpt_level":"N4","sort_order":220,"title":"Doing something for someone てあげる","pattern":"V-て + あげる","explanation":"てあげる describes the speaker or another person performing an action for the benefit of someone else. It can sound self-congratulatory when used about oneself toward a superior, so use it carefully.","formation":"Actor は recipient に + V-てあげる","category":"Giving and receiving","difficulty":"Challenge","examples":[{"japanese":"妹に日本語を教えてあげました。","romaji":"Imouto ni Nihongo o oshiete agemashita.","meaning":"I taught my younger sister Japanese for her benefit."},{"japanese":"友だちの荷物を持ってあげます。","romaji":"Tomodachi no nimotsu o motte agemasu.","meaning":"I will carry my friend's luggage for them."}],"common_mistakes":["Do not use てあげる casually when speaking about a favor to a superior.","Identify who performs the action and who benefits from it."]},{"jlpt_level":"N4","sort_order":230,"title":"Someone does something for me てくれる","pattern":"V-て + くれる","explanation":"てくれる describes another person doing something for the speaker or the speaker's in-group. It presents the action from the receiver's perspective and often expresses gratitude.","formation":"Actor が / は + V-てくれる","category":"Giving and receiving","difficulty":"Challenge","examples":[{"japanese":"友だちが手伝ってくれました。","romaji":"Tomodachi ga tetsudatte kuremashita.","meaning":"My friend helped me."},{"japanese":"母が駅まで迎えに来てくれます。","romaji":"Haha ga eki made mukae ni kite kuremasu.","meaning":"My mother will come to pick me up at the station."}],"common_mistakes":["The person receiving the benefit is usually the speaker or their in-group.","Do not confuse てくれる with てもらう, which presents the receiver as the subject."]},{"jlpt_level":"N4","sort_order":240,"title":"Receiving a favor てもらう","pattern":"V-て + もらう","explanation":"てもらう describes receiving the benefit of another person's action. The receiver is marked by は or が, and the person who performs the action is commonly marked by に or から.","formation":"Receiver は + actor に + V-てもらう","category":"Giving and receiving","difficulty":"Challenge","examples":[{"japanese":"先生に作文を直してもらいました。","romaji":"Sensei ni sakubun o naoshite moraimashita.","meaning":"I had my composition corrected by the teacher."},{"japanese":"友だちに駅まで送ってもらいました。","romaji":"Tomodachi ni eki made okutte moraimashita.","meaning":"I got a friend to take me to the station."}],"common_mistakes":["The receiver is the grammatical subject of てもらう.","てくれる and てもらう can describe the same event from different viewpoints."]},{"jlpt_level":"N4","sort_order":250,"title":"Humble receiving ていただく","pattern":"V-て + いただく","explanation":"ていただく is the humble and polite form of receiving someone's action. It is used to show respect to the person who performs the action and is common in formal requests, services, and professional settings.","formation":"V-て + いただく","category":"Giving and receiving","difficulty":"Challenge","examples":[{"japanese":"先生に説明していただきました。","romaji":"Sensei ni setsumei shite itadakimashita.","meaning":"I received an explanation from the teacher."},{"japanese":"こちらに名前を書いていただけますか。","romaji":"Kochira ni namae o kaite itadakemasu ka.","meaning":"Could you kindly write your name here?"}],"common_mistakes":["Use いただく when lowering the speaker's position relative to the person being respected.","Do not use this form for a casual favor among close friends."]},{"jlpt_level":"N4","sort_order":260,"title":"Past experience たことがある","pattern":"Vた + ことがある","explanation":"たことがある expresses that someone has had an experience at least once in their life or within a relevant period. The verb takes the plain past form before ことがある.","formation":"Verb past plain form + ことがある","category":"Experience","difficulty":"Core","examples":[{"japanese":"日本へ行ったことがあります。","romaji":"Nihon e itta koto ga arimasu.","meaning":"I have been to Japan."},{"japanese":"納豆を食べたことがありません。","romaji":"Nattou o tabeta koto ga arimasen.","meaning":"I have never eaten natto."}],"common_mistakes":["Use the past plain form before ことがある.","Do not use this pattern for a specific completed event with a precise past time."]},{"jlpt_level":"N4","sort_order":270,"title":"Personal decision ことにする","pattern":"V-dictionary / Vない + ことにする","explanation":"ことにする expresses a decision made by the speaker or a person in context. The verb before こと remains in dictionary or negative form according to the decision.","formation":"Verb dictionary / negative form + ことにする","category":"Decisions and plans","difficulty":"Core","examples":[{"japanese":"毎日三十分勉強することにしました。","romaji":"Mainichi sanjuppun benkyou suru koto ni shimashita.","meaning":"I decided to study for thirty minutes every day."},{"japanese":"夜はコーヒーを飲まないことにします。","romaji":"Yoru wa koohii o nomanai koto ni shimasu.","meaning":"I will decide not to drink coffee at night."}],"common_mistakes":["ことにする marks a decision by an agent; it is not the same as an externally arranged result.","Keep the verb in dictionary or negative form before こと."]},{"jlpt_level":"N4","sort_order":280,"title":"Arrangement or outcome ことになる","pattern":"V-dictionary / Vない + ことになる","explanation":"ことになる expresses that something has been decided, arranged, or determined by circumstances rather than being presented purely as the speaker's personal decision.","formation":"Verb dictionary / negative form + ことになる","category":"Decisions and plans","difficulty":"Core","examples":[{"japanese":"来月、大阪へ転勤することになりました。","romaji":"Raigetsu, Oosaka e tenkin suru koto ni narimashita.","meaning":"It has been decided that I will transfer to Osaka next month."},{"japanese":"会議は金曜日に行うことになりました。","romaji":"Kaigi wa kinyoubi ni okonau koto ni narimashita.","meaning":"It has been decided that the meeting will be held on Friday."}],"common_mistakes":["ことになる often implies an arrangement or decision by circumstances or others.","Contrast it with ことにする, which highlights the agent's choice."]},{"jlpt_level":"N4","sort_order":290,"title":"Change in ability or state ようになる","pattern":"V-dictionary / Vない + ようになる","explanation":"ようになる describes a gradual or meaningful change in ability, habit, or state. It often appears with potential verbs or repeated actions to show that something has become possible or has started happening.","formation":"Verb dictionary / negative form + ようになる","category":"Change and development","difficulty":"Core","examples":[{"japanese":"日本語の新聞が読めるようになりました。","romaji":"Nihongo no shinbun ga yomeru you ni narimashita.","meaning":"I have become able to read Japanese newspapers."},{"japanese":"最近、早く起きるようになりました。","romaji":"Saikin, hayaku okiru you ni narimashita.","meaning":"Recently I have started getting up early."}],"common_mistakes":["ようになる describes a change over time, not a single decision.","Use the potential form when the meaning is becoming able to do something."]},{"jlpt_level":"N4","sort_order":300,"title":"Make an effort to ようにする","pattern":"V-dictionary / Vない + ようにする","explanation":"ようにする expresses an effort, habit, or deliberate attempt to make something happen or avoid it. It focuses on the person's ongoing effort rather than a completed change.","formation":"Verb dictionary / negative form + ようにする","category":"Change and development","difficulty":"Core","examples":[{"japanese":"毎日、日本語を読むようにしています。","romaji":"Mainichi, Nihongo o yomu you ni shite imasu.","meaning":"I make a point of reading Japanese every day."},{"japanese":"遅れないようにしてください。","romaji":"Okurenai you ni shite kudasai.","meaning":"Please make sure not to be late."}],"common_mistakes":["ようにする describes effort or practice; ようになる describes a resulting change.","Use the negative form before ようにする when describing what to avoid."]},{"jlpt_level":"N4","sort_order":310,"title":"Intention つもり","pattern":"V-dictionary / Vない + つもり","explanation":"つもり expresses a speaker's intention or plan. It can describe a firm intention or, with a past form, a mistaken belief about what one did.","formation":"Verb dictionary / negative form + つもり","category":"Decisions and plans","difficulty":"Core","examples":[{"japanese":"来年、日本へ留学するつもりです。","romaji":"Rainen, Nihon e ryuugaku suru tsumori desu.","meaning":"I intend to study abroad in Japan next year."},{"japanese":"今日は出かけないつもりです。","romaji":"Kyou wa dekakenai tsumori desu.","meaning":"I do not intend to go out today."}],"common_mistakes":["Use dictionary form for intended actions and negative form for intended non-actions.","つもり is intention, while 予定 is a scheduled plan."]},{"jlpt_level":"N4","sort_order":320,"title":"Scheduled plan 予定","pattern":"V-dictionary / Nの + 予定","explanation":"予定 expresses a schedule or plan that has been arranged or is expected. It is often more objective than つもり and can refer to plans involving other people or fixed arrangements.","formation":"Verb dictionary form + 予定 / Noun + の + 予定","category":"Decisions and plans","difficulty":"Core","examples":[{"japanese":"来週、京都へ行く予定です。","romaji":"Raishuu, Kyoto e iku yotei desu.","meaning":"I am scheduled to go to Kyoto next week."},{"japanese":"会議は三時の予定です。","romaji":"Kaigi wa sanji no yotei desu.","meaning":"The meeting is scheduled for three o'clock."}],"common_mistakes":["Use dictionary form before 予定 for an action.","Do not confuse a personal intention with an established schedule."]},{"jlpt_level":"N4","sort_order":330,"title":"Expectation はずです","pattern":"Plain form + はずです","explanation":"はずです expresses a logical expectation based on information, evidence, or a known schedule. It means should, is expected to, or must be the case. Nouns and な-adjectives connect with のはずです / なはずです.","formation":"Plain form + はずです; Noun + のはず; な-adjective + なはず","category":"Expectations and probability","difficulty":"Challenge","examples":[{"japanese":"田中さんはもう家に着いたはずです。","romaji":"Tanaka-san wa mou ie ni tsuita hazu desu.","meaning":"Tanaka should have arrived home by now."},{"japanese":"この道をまっすぐ行けば、駅があるはずです。","romaji":"Kono michi o massugu ikeba, eki ga aru hazu desu.","meaning":"If you go straight along this road, the station should be there."}],"common_mistakes":["はず is based on an expectation, not merely a weak possibility.","Use の before はず after a noun and な after a な-adjective."]},{"jlpt_level":"N4","sort_order":340,"title":"Possibility かもしれない","pattern":"Plain form + かもしれない","explanation":"かもしれない expresses possibility or uncertainty. It is weaker than a confident prediction and can be translated as might or may. It commonly appears in both polite and casual forms.","formation":"Plain form + かもしれない / かもしれません","category":"Expectations and probability","difficulty":"Core","examples":[{"japanese":"午後、雨が降るかもしれません。","romaji":"Gogo, ame ga furu kamoshiremasen.","meaning":"It might rain this afternoon."},{"japanese":"彼はまだ知らないかもしれない。","romaji":"Kare wa mada shiranai kamoshirenai.","meaning":"He might not know yet."}],"common_mistakes":["Do not use だ between a plain noun predicate and かもしれない in the standard pattern.","This expression signals uncertainty, not a confirmed fact."]},{"jlpt_level":"N4","sort_order":350,"title":"Probable judgment でしょう","pattern":"Plain form + でしょう","explanation":"でしょう expresses a prediction or probability and can also seek agreement. It is often used in polite speech for a considered guess. Its certainty is generally stronger than かもしれない.","formation":"Plain form + でしょう","category":"Expectations and probability","difficulty":"Core","examples":[{"japanese":"明日は晴れるでしょう。","romaji":"Ashita wa hareru deshou.","meaning":"It will probably be sunny tomorrow."},{"japanese":"この問題は難しいでしょう。","romaji":"Kono mondai wa muzukashii deshou.","meaning":"This problem is probably difficult."}],"common_mistakes":["でしょう is a prediction or confirmation-seeking expression, not a simple yes-no question marker.","Use appropriate plain-form connections before でしょう."]},{"jlpt_level":"N4","sort_order":360,"title":"Indirect yes-no question かどうか","pattern":"Plain clause + かどうか","explanation":"かどうか embeds a yes-no question inside a larger sentence. It means whether or not and commonly appears with verbs such as 分かる, 知る, and 調べる.","formation":"Plain clause + かどうか + main verb","category":"Questions and embedded clauses","difficulty":"Core","examples":[{"japanese":"店が開いているかどうか分かりません。","romaji":"Mise ga aite iru ka dou ka wakarimasen.","meaning":"I do not know whether the shop is open."},{"japanese":"彼が来るかどうか聞いてください。","romaji":"Kare ga kuru ka dou ka kiite kudasai.","meaning":"Please ask whether he is coming."}],"common_mistakes":["Use かどうか for an embedded yes-no question, not a question word such as どこ.","The main sentence continues after the embedded clause."]},{"jlpt_level":"N4","sort_order":370,"title":"Only with a negative しか〜ない","pattern":"Noun + しか + negative","explanation":"しか〜ない means only or nothing but and requires a negative predicate. It often emphasizes that the amount or range is limited, sometimes with a sense of insufficiency.","formation":"Noun / quantity + しか + negative predicate","category":"Quantity and limitation","difficulty":"Challenge","examples":[{"japanese":"財布に千円しかありません。","romaji":"Saifu ni sen-en shika arimasen.","meaning":"I have only one thousand yen in my wallet."},{"japanese":"日曜日しか休めません。","romaji":"Nichiyoubi shika yasumemasen.","meaning":"I can only take a day off on Sunday."}],"common_mistakes":["しか must be paired with a negative predicate in this construction.","Do not use しか with an affirmative predicate when you mean only."]},{"jlpt_level":"N4","sort_order":380,"title":"All the time / nothing but ばかり","pattern":"Noun / Vた + ばかり","explanation":"ばかり can mean mostly, nothing but, or just did depending on what precedes it. With nouns it can indicate an excessive concentration; with a past verb it can mean that an action happened only a short time ago.","formation":"Noun + ばかり; Vた + ばかり","category":"Quantity and limitation","difficulty":"Challenge","examples":[{"japanese":"弟はゲームばかりしています。","romaji":"Otouto wa geemu bakari shite imasu.","meaning":"My younger brother does nothing but play games."},{"japanese":"昼ご飯を食べたばかりです。","romaji":"Hirugohan o tabeta bakari desu.","meaning":"I have just eaten lunch."}],"common_mistakes":["The meaning changes with the preceding form and context.","Do not confuse ばかり with だけ, which is a more neutral only."]},{"jlpt_level":"N4","sort_order":390,"title":"At the point of ところ","pattern":"V-dictionary / Vている / Vた + ところ","explanation":"ところ shows the stage of an action: just about to do it, currently doing it, or just finished doing it. The verb form before ところ determines the timing.","formation":"V-dictionary + ところ; V-ている + ところ; Vた + ところ","category":"Time and sequence","difficulty":"Challenge","examples":[{"japanese":"今から出かけるところです。","romaji":"Ima kara dekakeru tokoro desu.","meaning":"I am just about to go out."},{"japanese":"今、昼ご飯を食べているところです。","romaji":"Ima, hirugohan o tabete iru tokoro desu.","meaning":"I am eating lunch right now."}],"common_mistakes":["Use the dictionary form for just about to, ている for in the middle of, and た for just finished.","Do not assume ところ always refers to a physical place."]},{"jlpt_level":"N4","sort_order":400,"title":"During a period 間","pattern":"Noun / Vている + 間","explanation":"間 describes a period during which a state or activity continues. It focuses on the whole interval and often introduces an action that takes place throughout that time.","formation":"Noun + の + 間; V-ている + 間","category":"Time and sequence","difficulty":"Core","examples":[{"japanese":"夏休みの間、毎日泳ぎました。","romaji":"Natsuyasumi no aida, mainichi oyogimashita.","meaning":"I swam every day during the summer holiday."},{"japanese":"母が料理している間、私は本を読みました。","romaji":"Haha ga ryouri shite iru aida, watashi wa hon o yomimashita.","meaning":"I read a book while my mother was cooking."}],"common_mistakes":["Use 間 when the action or state continues through the period.","Use 間に when something happens at some point within the interval."]},{"jlpt_level":"N4","sort_order":410,"title":"Within a period 間に","pattern":"Noun / Vている + 間に","explanation":"間に marks a point or event that occurs within a time interval. Unlike 間, which emphasizes the whole period, 間に focuses on something happening before that interval ends.","formation":"Noun + の + 間に; V-ている + 間に","category":"Time and sequence","difficulty":"Challenge","examples":[{"japanese":"留守の間に、荷物が届きました。","romaji":"Rusu no aida ni, nimotsu ga todokimashita.","meaning":"A parcel arrived while I was away."},{"japanese":"母が寝ている間に、掃除しました。","romaji":"Haha ga nete iru aida ni, souji shimashita.","meaning":"I cleaned while my mother was sleeping."}],"common_mistakes":["間に often introduces an event that happens once within a period.","Do not use 間 and 間に interchangeably without considering duration and event structure."]},{"jlpt_level":"N4","sort_order":420,"title":"Deadline までに","pattern":"Time + までに","explanation":"までに means by a deadline or before a specified time. It marks the latest point at which an action must be completed, rather than a duration that continues until that time.","formation":"Deadline + までに + action","category":"Time and sequence","difficulty":"Core","examples":[{"japanese":"金曜日までにレポートを出してください。","romaji":"Kinyoubi made ni repooto o dashite kudasai.","meaning":"Please submit the report by Friday."},{"japanese":"九時までに来てください。","romaji":"Ku-ji made ni kite kudasai.","meaning":"Please come by nine o'clock."}],"common_mistakes":["までに marks a completion deadline; まで alone marks an endpoint or duration.","Do not interpret までに as by the time repeatedly across an interval."]},{"jlpt_level":"N4","sort_order":430,"title":"Equal distribution ずつ","pattern":"Number / amount + ずつ","explanation":"ずつ distributes an amount equally or describes gradual change in equal increments. It can follow counters, quantities, or certain adverbs.","formation":"Number / counter + ずつ","category":"Quantity and limitation","difficulty":"Core","examples":[{"japanese":"りんごを二つずつ配ります。","romaji":"Ringo o futatsu zutsu kubarimasu.","meaning":"I will distribute two apples to each person."},{"japanese":"毎日少しずつ覚えます。","romaji":"Mainichi sukoshi zutsu oboemasu.","meaning":"I memorize a little at a time every day."}],"common_mistakes":["ずつ indicates equal portions or increments, not an approximate amount.","Place it after the number or quantity being distributed."]},{"jlpt_level":"N4","sort_order":440,"title":"Every time たびに","pattern":"V-dictionary / Nの + たびに","explanation":"たびに means every time or whenever. It describes a repeated result or reaction that occurs on each occasion of an event.","formation":"Verb dictionary form + たびに; Noun + の + たびに","category":"Time and sequence","difficulty":"Challenge","examples":[{"japanese":"この写真を見るたびに、旅行を思い出します。","romaji":"Kono shashin o miru tabi ni, ryokou o omoidasu.","meaning":"Every time I see this photo, I remember the trip."},{"japanese":"試験のたびに緊張します。","romaji":"Shiken no tabi ni kinchou shimasu.","meaning":"I get nervous every time there is an exam."}],"common_mistakes":["Use dictionary form before たびに.","たびに describes repeated occasions, not a single deadline."]},{"jlpt_level":"N4","sort_order":450,"title":"Advice た方がいい","pattern":"Vた / Vない + 方がいい","explanation":"方がいい gives advice or a recommendation. Use the plain past form for recommended actions and the plain negative form to recommend against an action.","formation":"Vた + 方がいい; Vない + 方がいい","category":"Advice and obligation","difficulty":"Core","examples":[{"japanese":"早く寝た方がいいです。","romaji":"Hayaku neta hou ga ii desu.","meaning":"You should go to bed early."},{"japanese":"そんなに心配しない方がいいです。","romaji":"Sonna ni shinpai shinai hou ga ii desu.","meaning":"You should not worry so much."}],"common_mistakes":["Use the past plain form for positive recommendations and the negative plain form for negative recommendations.","This is advice, not a rule that the listener must obey."]},{"jlpt_level":"N4","sort_order":460,"title":"Excess すぎる","pattern":"V-masu stem / adjective stem + すぎる","explanation":"すぎる expresses excess: too much, too many, or too. Attach it to the verb stem, remove い from an い-adjective, or add it to a な-adjective without な.","formation":"Verb stem + すぎる; い-adjective stem + すぎる; な-adjective + すぎる","category":"Verb and adjective nuance","difficulty":"Core","examples":[{"japanese":"昨日、食べすぎました。","romaji":"Kinou, tabesugimashita.","meaning":"I ate too much yesterday."},{"japanese":"この部屋は静かすぎます。","romaji":"Kono heya wa shizuka sugimasu.","meaning":"This room is too quiet."}],"common_mistakes":["Remove the final い from an い-adjective before すぎる.","Do not keep な before すぎる after a な-adjective."]},{"jlpt_level":"N4","sort_order":470,"title":"Obligation なければならない","pattern":"Vない stem + ければならない","explanation":"なければならない expresses obligation or necessity. It is formed from the negative base of a verb and means must or have to. The exact politeness can vary by ending.","formation":"Verb ない-form without い + ければならない","category":"Advice and obligation","difficulty":"Challenge","examples":[{"japanese":"明日、早く起きなければなりません。","romaji":"Ashita, hayaku okinakereba narimasen.","meaning":"I have to get up early tomorrow."},{"japanese":"宿題を出さなければなりません。","romaji":"Shukudai o dasanakereba narimasen.","meaning":"I must submit my homework."}],"common_mistakes":["Start from the verb ない-form and remove its final い.","Do not confuse obligation with permission or advice."]},{"jlpt_level":"N4","sort_order":480,"title":"No need なくてもいい","pattern":"Vない without い + くてもいい","explanation":"なくてもいい means that an action does not have to be done. It grants permission not to do something; it does not prohibit the action.","formation":"Verb ない-form without い + くてもいい","category":"Advice and obligation","difficulty":"Core","examples":[{"japanese":"明日は来なくてもいいです。","romaji":"Ashita wa konakute mo ii desu.","meaning":"You do not have to come tomorrow."},{"japanese":"全部食べなくてもいいです。","romaji":"Zenbu tabenakute mo ii desu.","meaning":"You do not have to eat everything."}],"common_mistakes":["なくてもいい means not necessary, not not allowed.","Use てはいけません for prohibition."]},{"jlpt_level":"N4","sort_order":490,"title":"Do not do ないでください","pattern":"Vない + でください","explanation":"ないでください is a polite request not to perform an action. It is formed from the plain negative form of a verb followed by でください.","formation":"Verb ない-form + でください","category":"Requests and permission","difficulty":"Core","examples":[{"japanese":"ここで写真を撮らないでください。","romaji":"Koko de shashin o toranaide kudasai.","meaning":"Please do not take photographs here."},{"japanese":"心配しないでください。","romaji":"Shinpai shinaide kudasai.","meaning":"Please do not worry."}],"common_mistakes":["Use the complete negative form before でください.","Do not confuse this request with なくてもいい, which means there is no need to act."]},{"jlpt_level":"N4","sort_order":500,"title":"Try to avoid ないようにする","pattern":"Vない + ようにする","explanation":"ないようにする expresses an effort or habit of avoiding an action. It focuses on the speaker's deliberate effort to prevent something from happening.","formation":"Verb ない-form + ようにする","category":"Change and development","difficulty":"Challenge","examples":[{"japanese":"遅れないようにしています。","romaji":"Okurenai you ni shite imasu.","meaning":"I make an effort not to be late."},{"japanese":"同じ間違いをしないようにします。","romaji":"Onaji machigai o shinai you ni shimasu.","meaning":"I will try not to make the same mistake."}],"common_mistakes":["This expresses an effort to avoid an event, not a simple prohibition.","Use ない-form before ようにする."]},{"jlpt_level":"N4","sort_order":510,"title":"Suggestion たらどうですか","pattern":"Vた + らどうですか","explanation":"たらどうですか suggests that someone try an action. It can sound direct depending on tone, so use it with care in formal or delicate situations.","formation":"Verb past plain form + らどうですか","category":"Advice and obligation","difficulty":"Core","examples":[{"japanese":"病院へ行ったらどうですか。","romaji":"Byouin e ittara dou desu ka.","meaning":"Why don't you go to the hospital?"},{"japanese":"先生に聞いてみたらどうですか。","romaji":"Sensei ni kiite mitara dou desu ka.","meaning":"Why don't you try asking the teacher?"}],"common_mistakes":["Use the past plain form before らどうですか.","This is a suggestion, not a literal question about a past event."]},{"jlpt_level":"N4","sort_order":520,"title":"Potential form for ability","pattern":"Potential verb form","explanation":"The potential form expresses ability or possibility: can do something. Group 1 verbs change the final u-row sound to the corresponding e-row sound and add る; Group 2 verbs replace る with られる; する becomes できる and 来る becomes 来られる.","formation":"Group 1: e-row + る; Group 2: remove る + られる; する → できる","category":"Verb forms","difficulty":"Challenge","examples":[{"japanese":"漢字が読めます。","romaji":"Kanji ga yomemasu.","meaning":"I can read kanji."},{"japanese":"ここでカードが使えます。","romaji":"Koko de kaado ga tsukaemasu.","meaning":"You can use cards here."}],"common_mistakes":["Do not confuse potential forms with passive forms that may share a similar shape.","With many potential verbs, the ability target is marked by が."]},{"jlpt_level":"N4","sort_order":530,"title":"Passive voice","pattern":"Passive verb form","explanation":"The passive form presents the subject as the person or thing affected by an action. It is useful for neutral descriptions, formal writing, and expressing an unwanted action or inconvenience.","formation":"Group 1: a-row + れる; Group 2: remove る + られる; する → される","category":"Verb forms","difficulty":"Challenge","examples":[{"japanese":"この本は多くの人に読まれています。","romaji":"Kono hon wa ooku no hito ni yomarete imasu.","meaning":"This book is read by many people."},{"japanese":"私は先生にほめられました。","romaji":"Watashi wa sensei ni homeraremashita.","meaning":"I was praised by the teacher."}],"common_mistakes":["Mark the agent with に when it is stated.","Distinguish passive voice from potential forms, especially with Group 2 verbs."]},{"jlpt_level":"N4","sort_order":540,"title":"Causative form","pattern":"Causative verb form","explanation":"The causative form expresses making or letting someone do something. The exact interpretation depends on context, the verb, and the relationship between the people involved.","formation":"Group 1: a-row + せる; Group 2: remove る + させる; する → させる","category":"Verb forms","difficulty":"Challenge","examples":[{"japanese":"母は子どもに野菜を食べさせました。","romaji":"Haha wa kodomo ni yasai o tabesasemashita.","meaning":"The mother made the child eat vegetables."},{"japanese":"先生は学生を早く帰らせました。","romaji":"Sensei wa gakusei o hayaku kaerasemashita.","meaning":"The teacher let the students go home early."}],"common_mistakes":["Causative can mean make or let; do not assume only one meaning.","The person being made or allowed to act is marked according to the verb and transitivity."]},{"jlpt_level":"N4","sort_order":550,"title":"Degree comparison ほど〜ない","pattern":"A は B ほど adjective-negative","explanation":"ほど〜ない expresses that A is not as much or as ... as B. It compares degree and usually places the adjective in a negative form.","formation":"A は B ほど + adjective negative","category":"Comparisons","difficulty":"Challenge","examples":[{"japanese":"今日は昨日ほど寒くないです。","romaji":"Kyou wa kinou hodo samukunai desu.","meaning":"Today is not as cold as yesterday."},{"japanese":"この本はあの本ほど難しくありません。","romaji":"Kono hon wa ano hon hodo muzukashiku arimasen.","meaning":"This book is not as difficult as that one."}],"common_mistakes":["The adjective after ほど is normally negative in this comparison pattern.","Do not confuse ほど〜ない with より, which states a positive comparison."]},{"jlpt_level":"N4","sort_order":560,"title":"Resulting state てある","pattern":"V-て + ある","explanation":"てある describes a state that remains as the result of someone intentionally performing an action. It is commonly used with transitive verbs and often leaves the agent unstated.","formation":"Transitive verb て-form + ある","category":"Verb nuance","difficulty":"Challenge","examples":[{"japanese":"窓が開けてあります。","romaji":"Mado ga akete arimasu.","meaning":"The window has been left open."},{"japanese":"机の上に資料が置いてあります。","romaji":"Tsukue no ue ni shiryou ga oite arimasu.","meaning":"The documents have been placed on the desk."}],"common_mistakes":["てある focuses on a resulting state caused by an intentional action.","Use a transitive verb; contrast it with intransitive ている descriptions."]},{"jlpt_level":"N4","sort_order":570,"title":"Easy to do やすい","pattern":"V-masu stem + やすい","explanation":"やすい attaches to the verb stem and means easy to do. It forms an い-adjective, so it can take adjective endings such as くない and かった.","formation":"Verb stem + やすい","category":"Verb and adjective nuance","difficulty":"Core","examples":[{"japanese":"このペンは書きやすいです。","romaji":"Kono pen wa kakiyasui desu.","meaning":"This pen is easy to write with."},{"japanese":"この道は歩きやすいです。","romaji":"Kono michi wa arukiyasui desu.","meaning":"This road is easy to walk along."}],"common_mistakes":["Attach やすい to the verb stem, not the dictionary form.","Conjugate the whole expression like an い-adjective."]},{"jlpt_level":"N4","sort_order":580,"title":"Difficult to do にくい","pattern":"V-masu stem + にくい","explanation":"にくい attaches to the verb stem and means difficult to do. It describes an action that is hard to perform and behaves like an い-adjective.","formation":"Verb stem + にくい","category":"Verb and adjective nuance","difficulty":"Core","examples":[{"japanese":"この漢字は覚えにくいです。","romaji":"Kono kanji wa oboenikui desu.","meaning":"This kanji is difficult to memorize."},{"japanese":"この靴は歩きにくいです。","romaji":"Kono kutsu wa arukiniku i desu.","meaning":"These shoes are difficult to walk in."}],"common_mistakes":["Attach にくい to the verb stem.","Keep the expression together when conjugating it as an adjective."]},{"jlpt_level":"N4","sort_order":590,"title":"Simultaneous actions ながら","pattern":"V-masu stem + ながら","explanation":"ながら connects two actions performed by the same person at the same time. The main action usually appears after ながら, while the action before it provides the accompanying activity.","formation":"Verb stem + ながら + main action","category":"Connecting ideas","difficulty":"Core","examples":[{"japanese":"音楽を聞きながら勉強します。","romaji":"Ongaku o kikinagara benkyou shimasu.","meaning":"I study while listening to music."},{"japanese":"歩きながら電話しないでください。","romaji":"Arukinagara denwa shinaide kudasai.","meaning":"Please do not talk on the phone while walking."}],"common_mistakes":["Both actions normally have the same subject.","The main point of the sentence is usually the action after ながら."]},{"jlpt_level":"N4","sort_order":600,"title":"Not very / not much あまり〜ない","pattern":"あまり + negative","explanation":"あまり combines with a negative predicate to mean not very or not much. It softens a negative statement and is common with adjectives, adverbs, and verbs of frequency.","formation":"あまり + negative predicate","category":"Degree and frequency","difficulty":"Core","examples":[{"japanese":"この映画はあまりおもしろくないです。","romaji":"Kono eiga wa amari omoshiroku nai desu.","meaning":"This film is not very interesting."},{"japanese":"最近、あまりテレビを見ません。","romaji":"Saikin, amari terebi o mimasen.","meaning":"I do not watch much television recently."}],"common_mistakes":["あまり normally takes a negative predicate in this meaning.","Do not omit the negative ending."]},{"jlpt_level":"N4","sort_order":610,"title":"Not easily / not readily なかなか〜ない","pattern":"なかなか + negative","explanation":"なかなか with a negative predicate means that something does not happen easily or as expected. It expresses difficulty, delay, or frustration.","formation":"なかなか + negative predicate","category":"Degree and frequency","difficulty":"Challenge","examples":[{"japanese":"バスがなかなか来ません。","romaji":"Basu ga nakanaka kimasen.","meaning":"The bus is not coming easily / is taking a long time."},{"japanese":"漢字の名前がなかなか覚えられません。","romaji":"Kanji no namae ga nakanaka oboeraremasen.","meaning":"I cannot easily remember the kanji names."}],"common_mistakes":["With a negative predicate, なかなか often implies an unexpected delay or difficulty.","Do not translate it as quite or very in this negative pattern."]},{"jlpt_level":"N4","sort_order":620,"title":"Change into a state になる","pattern":"N / な-adjective / い-adjective + なる","explanation":"なる expresses a change of state. Nouns and な-adjectives connect with に; い-adjectives change final い to く before なる.","formation":"Noun / な-adjective + に + なる; い-adjective く + なる","category":"Change and development","difficulty":"Core","examples":[{"japanese":"医者になりました。","romaji":"Isha ni narimashita.","meaning":"I became a doctor."},{"japanese":"だんだん暖かくなりました。","romaji":"Dandan atatakaku narimashita.","meaning":"It gradually became warmer."}],"common_mistakes":["Use に after a noun or な-adjective and く after an い-adjective.","なる describes a change; する often describes making a change intentionally."]},{"jlpt_level":"N4","sort_order":630,"title":"Make something a certain way する","pattern":"N / な-adjective / い-adjective + する","explanation":"する expresses intentionally making something a certain state or choosing a particular option. Nouns and な-adjectives connect with に; い-adjectives change final い to く.","formation":"Noun / な-adjective + に + する; い-adjective く + する","category":"Change and development","difficulty":"Challenge","examples":[{"japanese":"部屋をきれいにします。","romaji":"Heya o kirei ni shimasu.","meaning":"I will make the room clean."},{"japanese":"音を小さくしてください。","romaji":"Oto o chiisaku shite kudasai.","meaning":"Please turn the volume down."}],"common_mistakes":["する emphasizes an intentional action; なる emphasizes a change or result.","Use the correct に or く connector for the adjective type."]},{"jlpt_level":"N4","sort_order":640,"title":"Only / just だけ","pattern":"Noun / plain form + だけ","explanation":"だけ marks a limit or restriction and means only or just. Unlike しか, it can be used with an affirmative predicate and is relatively neutral.","formation":"Noun / plain form + だけ","category":"Quantity and limitation","difficulty":"Core","examples":[{"japanese":"今日は水だけ飲みました。","romaji":"Kyou wa mizu dake nomimashita.","meaning":"Today I drank only water."},{"japanese":"できるだけ早く来てください。","romaji":"Dekiru dake hayaku kite kudasai.","meaning":"Please come as early as possible."}],"common_mistakes":["だけ does not require a negative predicate; しか does.","Check whether the intended meaning is a neutral limit or an emphasized shortage."]}]$curriculum$::jsonb) as item
)
insert into public.grammar_points (
  jlpt_level, title, pattern, explanation, formation, examples, common_mistakes,
  category, difficulty, sort_order, publication_status
)
select
  jlpt_level, title, pattern, explanation, formation, examples, common_mistakes,
  category, difficulty, sort_order, 'published'
from curriculum
on conflict (jlpt_level, pattern) do update set
  title = excluded.title,
  explanation = excluded.explanation,
  formation = excluded.formation,
  examples = excluded.examples,
  common_mistakes = excluded.common_mistakes,
  category = excluded.category,
  difficulty = excluded.difficulty,
  sort_order = excluded.sort_order,
  publication_status = 'published',
  updated_at = now();

comment on table public.user_grammar_progress is
  'Per-user completion state for published grammar points; one row per learner and grammar point.';

commit;
